// Curios Songs: an original song inspired by a song, artist or album from the Music page.
// Lyrics are written and edited here with Luna (cheap); the music itself is generated by
// ElevenLabs Music (ELEVENLAB_API_KEY, which has the Music permission; Lyria stays off until
// Google billing is back). Lyrics are always ORIGINAL: never lines from the inspiration or any other song,
// never artist or song names (music models refuse them, and they are not ours to use).
//
// Body { action, … }:
//   ideas   { inspiration, language }                         → { ideas: string[] }
//   draft   { inspiration, language, idea?, style? }          → { song: SongDraft }
//   rewrite { inspiration, language, song, part, mood? }      → { lines: string[] }
//   check   { language, part, lines, original? }              → { lines: LineCheck[] }
//   status                                                    → { music: boolean }
//   generate { inspiration, language, song, style, styleSound, voice, length, idea } → { id }
//   stems    { id }  → { instrumentalUrl } (voice off; separated once, then cached on the row)
import { unzipSync } from "npm:fflate@0.8.2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

// @ts-ignore: Deno.env is available in Supabase Edge Functions runtime
const OPENAI_API_KEY = Deno.env.get("OPENAI_API_KEY") ?? "";
// @ts-ignore: Deno.env is available in Supabase Edge Functions runtime
const ELEVENLABS_MUSIC_API_KEY = Deno.env.get("ELEVENLABS_MUSIC_API_KEY") || Deno.env.get("ELEVENLAB_API_KEY") || "";
// @ts-ignore: Deno.env is available in Supabase Edge Functions runtime
const SUPABASE_URL = Deno.env.get("SUPABASE_URL") ?? "";
// @ts-ignore: Deno.env is available in Supabase Edge Functions runtime
const SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
// @ts-ignore: Deno.env is available in Supabase Edge Functions runtime
const ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY") ?? "";
const ELEVEN = "https://api.elevenlabs.io/v1";
const BUCKET = "movie-assets";

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

interface Inspiration { kind: string; title: string; artist: string; year?: string; genres?: string[]; about?: string }
interface Part { id: string; type: "verse" | "chorus" | "bridge"; lines: string[] }

async function luna(system: string, user: string, maxTokens: number, effort: "none" | "low" = "none"): Promise<any> {
  const res = await fetch("https://api.openai.com/v1/responses", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${OPENAI_API_KEY}` },
    body: JSON.stringify({
      model: "gpt-6-luna",
      input: [{ role: "system", content: system }, { role: "user", content: user }],
      max_output_tokens: maxTokens,
      reasoning: { effort },
      text: { format: { type: "json_object" } },
    }),
    signal: AbortSignal.timeout(30000),
  });
  if (!res.ok) throw new Error(`Luna ${res.status}: ${(await res.text()).slice(0, 200)}`);
  const data = await res.json();
  const text = data.output_text ?? data.output?.flatMap((o: any) => o.content ?? []).map((c: any) => c.text ?? "").join("") ?? "";
  return JSON.parse(text);
}

const describe = (i: Inspiration) =>
  `${i.kind === "artist" ? `the artist ${i.artist}` : `the ${i.kind === "album" ? "album" : "song"} "${i.title}" by ${i.artist}`}${i.year ? ` (${i.year})` : ""}${i.genres?.length ? `, genres: ${i.genres.join(", ")}` : ""}${i.about ? `. About it: ${i.about.slice(0, 500)}` : ""}`;

const ORIGINAL_RULES = `The lyrics must be 100% ORIGINAL: never copy, quote or paraphrase lines, hooks or distinctive phrases from the inspiration or any existing song, and never name real artists, bands or songs. Capture its themes, mood, imagery and structure instead.`;

// Luna follows the inspiration's language unless told twice (an English song → English lyrics).
const inLanguage = (language: string) => `Write every lyric line, the title and the mood buttons in language "${language}", even when the inspiration is in another language.`;

const LINE_RULES = `Singable lines of 5–10 words (max 60 characters), a clear rhyme scheme (AABB or ABAB) within each part, similar syllable counts in a part, and a chorus that works as a repeatable hook.`;

const strings = (xs: unknown, max: number) =>
  (Array.isArray(xs) ? xs : []).filter((x) => typeof x === "string" && x.trim()).map((x: string) => x.trim().slice(0, 80)).slice(0, max);

// ---------- Music (ElevenLabs) ----------
interface Word { word: string; start_ms: number; end_ms: number }
const SUNG_ORDER: Record<string, string[]> = {
  short: ["verse1", "chorus"],
  long: ["verse1", "chorus", "verse2", "chorus", "bridge", "chorus"],
};
const SECTION_NAME: Record<string, string> = { verse1: "Verse 1", verse2: "Verse 2", chorus: "Chorus", bridge: "Bridge" };
const LOCAL_STYLE: Record<string, string[]> = {
  verse1: ["storytelling", "builds gently"],
  verse2: ["storytelling", "more energy"],
  chorus: ["full arrangement", "catchy hook", "powerful"],
  bridge: ["contrast", "breakdown", "emotional peak"],
};

// Our own plan: the parts in sung order, an instrumental intro and outro, the chosen sound.
function compositionPlan(parts: Part[], order: string[], sound: string, sung: boolean, language: string) {
  const langName = new Intl.DisplayNames(["en"], { type: "language" }).of(language) ?? language;
  const tags = sound.split(/[,;]+/).map((x) => x.trim()).filter(Boolean).slice(0, 8);
  const byId = new Map(parts.map((p) => [p.id, p]));
  const sections = order.filter((id) => byId.has(id)).map((id, i) => {
    const lines = byId.get(id)!.lines;
    return {
      section_name: `${SECTION_NAME[id]}${order.indexOf(id) !== i ? ` ${i}` : ""}`,
      positive_local_styles: sung ? LOCAL_STYLE[id] : [...LOCAL_STYLE[id], "instrumental"],
      negative_local_styles: [],
      duration_ms: Math.min(40000, Math.max(10000, lines.length * 4500 + 2000)),
      lines: sung ? lines : [],
    };
  });
  return {
    positive_global_styles: [...tags, sung ? `${langName} vocals` : "instrumental"],
    negative_global_styles: sung ? [] : ["vocals", "singing"],
    sections: [
      { section_name: "Intro", positive_local_styles: ["instrumental intro"], negative_local_styles: ["vocals"], duration_ms: 6000, lines: [] },
      ...sections,
      { section_name: "Outro", positive_local_styles: ["instrumental ending"], negative_local_styles: ["vocals"], duration_ms: 6000, lines: [] },
    ],
  };
}

// /music/detailed answers multipart/mixed: a JSON part (plan + word timestamps) and the mp3.
function splitMultipart(bytes: Uint8Array, contentType: string): { json: any; audio: Uint8Array } {
  const boundary = contentType.match(/boundary=([^;]+)/)?.[1];
  if (!boundary) throw new Error("No multipart boundary");
  const dec = new TextDecoder("latin1");
  const text = dec.decode(bytes);
  let jsonPart: any = null;
  let audio: Uint8Array | null = null;
  // latin1 keeps one char per byte, so text offsets are byte offsets.
  let offset = 0;
  for (const chunk of text.split(`--${boundary}`)) {
    const chunkStart = offset;
    offset += chunk.length + boundary.length + 2;
    const sep = chunk.indexOf("\r\n\r\n");
    if (sep < 0) continue;
    const head = chunk.slice(0, sep);
    const start = chunkStart + sep + 4;
    let end = chunkStart + chunk.length;
    while (end > start && (text[end - 1] === "\n" || text[end - 1] === "\r")) end--;
    if (/application\/json/i.test(head)) jsonPart = JSON.parse(new TextDecoder().decode(bytes.slice(start, end)));
    else if (/audio\//i.test(head)) audio = bytes.slice(start, end);
  }
  if (!audio) throw new Error("No audio in the music response");
  return { json: jsonPart, audio };
}

// Lines as sung, each with its words' times (the model returns one timestamp per lyric word).
function captionsFrom(lines: string[], words: Word[]) {
  let k = 0;
  const out = [];
  for (const text of lines) {
    const n = text.split(/\s+/).filter(Boolean).length;
    const ws = words.slice(k, k + n);
    k += n;
    if (!ws.length) break;
    out.push({ text, start_ms: ws[0].start_ms, end_ms: ws[ws.length - 1].end_ms, words: ws.map((w) => ({ w: w.word, s: w.start_ms, e: w.end_ms })) });
  }
  return out;
}

async function upload(path: string, bytes: Uint8Array, type: string): Promise<string> {
  const res = await fetch(`${SUPABASE_URL}/storage/v1/object/${BUCKET}/${path}`, {
    method: "POST",
    headers: { apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}`, "Content-Type": type, "x-upsert": "true" },
    body: bytes,
  });
  if (!res.ok) throw new Error(`Storage ${res.status}: ${(await res.text()).slice(0, 200)}`);
  return `${SUPABASE_URL}/storage/v1/object/public/${BUCKET}/${path}`;
}

const rest = (path: string, init: RequestInit = {}) =>
  fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
    ...init,
    headers: { apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}`, "Content-Type": "application/json", ...(init.headers ?? {}) },
  });

// The signed-in creator (the app sends the user's access token); guests → anonymous.
async function creatorOf(req: Request): Promise<{ creator_id: string | null; creator_name: string | null }> {
  const token = req.headers.get("Authorization")?.replace(/^Bearer\s+/i, "") ?? "";
  if (!token || token === ANON_KEY) return { creator_id: null, creator_name: null };
  try {
    const res = await fetch(`${SUPABASE_URL}/auth/v1/user`, { headers: { apikey: ANON_KEY, Authorization: `Bearer ${token}` } });
    if (!res.ok) return { creator_id: null, creator_name: null };
    const u = await res.json();
    const m = u.user_metadata ?? {};
    // Profile name only — never derived from the email (it would be public on the cards).
    const name = m.full_name || m.name || m.user_name || null;
    return { creator_id: u.id ?? null, creator_name: name ? String(name).slice(0, 40) : null };
  } catch {
    return { creator_id: null, creator_name: null };
  }
}

// ---------- Animations: three canvas visualizers written for this song ----------
const ANIMATION_PROMPT = `You write three small canvas animations that play on top of an original song, as plain JavaScript.
The page gives you these globals: ctx (CanvasRenderingContext2D), W and H (canvas size; read them every frame, they change on resize), P (5 hex colors, P[0] = background).
Define exactly: function setup() {} (once) and function draw(t, a) {} (every frame; t = seconds). a = { level: 0..1 loudness, bass: 0..1, high: 0..1, beat: true on a beat, section: "intro"|"verse"|"chorus"|"bridge"|"outro", line: the lyric line being sung or "", progress: 0..1 of the song }.
Rules: paint the whole background every frame; no DOM, network, timers, storage, eval, async or while loops; at most 300 objects; keep each frame fast. Every animation must visibly move with a.level and pulse on a.beat, and grow brighter or bigger in the chorus. Use only P's colors (with alpha).
- "abstract": flowing lines and geometric shapes.
- "drawn": a simple animated DRAWING of the song's central image built from basic shapes (circles, rectangles, paths), e.g. a yellow submarine gliding between bubbles; a few elements move to the music.
- "particles": particles, waves or orbits.
Reply with strict JSON {"palette":["#rrggbb" x5], "abstract":"<code>", "drawn":"<code>", "particles":"<code>"}.`;

async function writeAnimations(title: string, lyrics: string, sound: string): Promise<{ palette: string[]; animations: Record<string, string> }> {
  const res = await fetch("https://api.openai.com/v1/responses", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${OPENAI_API_KEY}` },
    body: JSON.stringify({
      model: "gpt-6.1-sol",
      input: [{ role: "system", content: ANIMATION_PROMPT }, { role: "user", content: `Song "${title}" (${sound}).\nLyrics:\n${lyrics}` }],
      max_output_tokens: 9000,
      reasoning: { effort: "low" },
      text: { format: { type: "json_object" } },
    }),
    signal: AbortSignal.timeout(110000),
  });
  if (!res.ok) throw new Error(`Animations ${res.status}`);
  const data = await res.json();
  const text = data.output_text ?? data.output?.flatMap((o: any) => o.content ?? []).map((c: any) => c.text ?? "").join("") ?? "";
  const out = JSON.parse(text);
  const palette = (Array.isArray(out?.palette) ? out.palette : []).filter((c: unknown) => typeof c === "string" && /^#[0-9a-f]{6}$/i.test(c)).slice(0, 5);
  const animations: Record<string, string> = {};
  for (const k of ["abstract", "drawn", "particles"]) {
    const code = typeof out?.[k] === "string" ? out[k] : "";
    // Syntax check here; runtime errors fall back to the page's built-in visualizer.
    try { new Function(code); if (/function\s+draw\s*\(/.test(code)) animations[k] = code.slice(0, 20000); } catch { /* skipped */ }
  }
  return { palette: palette.length === 5 ? palette : [], animations };
}

async function generate(req: Request, body: any, insp: Inspiration, language: string) {
  const song = body.song as { title: string; sound: string; parts: Part[] };
  const length = body.length === "long" ? "long" : "short";
  const sung = body.voice !== false;
  const style = typeof body.style === "string" ? body.style.slice(0, 30) : "original";
  const sound = (style === "original" ? song.sound : String(body.styleSound ?? "")).slice(0, 200) || song.sound;
  const order = SUNG_ORDER[length];
  const plan = compositionPlan(song.parts, order, sound, sung, language);
  const sungLines = plan.sections.flatMap((s) => s.lines);

  const [music, art, creator] = await Promise.all([
    (async () => {
      const res = await fetch(`${ELEVEN}/music/detailed?output_format=mp3_44100_128`, {
        method: "POST",
        headers: { "xi-api-key": ELEVENLABS_MUSIC_API_KEY, "Content-Type": "application/json" },
        body: JSON.stringify({ composition_plan: plan, model_id: "music_v1", with_timestamps: sung }),
        signal: AbortSignal.timeout(140000),
      });
      if (!res.ok) throw new Error(`ElevenLabs ${res.status}: ${(await res.text()).slice(0, 300)}`);
      return splitMultipart(new Uint8Array(await res.arrayBuffer()), res.headers.get("content-type") ?? "");
    })(),
    writeAnimations(song.title, sungLines.join("\n") || song.title, sound).catch((err) => {
      console.error("animations failed", String(err));
      return { palette: [], animations: {} };
    }),
    creatorOf(req),
  ]);

  const id = crypto.randomUUID();
  const audioUrl = await upload(`songs/${id}.mp3`, music.audio, "audio/mpeg");
  const words: Word[] = music.json?.words_timestamps ?? [];
  const captions = sung ? captionsFrom(sungLines, words) : [];
  const durationMs = plan.sections.reduce((n, s) => n + s.duration_ms, 0);
  const row = {
    id,
    title: song.title.slice(0, 80),
    inspired_by: insp.kind === "artist" ? insp.artist : insp.title,
    inspired_artist: insp.artist,
    style,
    language,
    voice: sung,
    length,
    idea: typeof body.idea === "string" ? body.idea.slice(0, 200) : null,
    lyrics: { parts: song.parts, order },
    captions,
    audio_url: audioUrl,
    duration_ms: durationMs,
    palette: art.palette,
    animations: art.animations,
    genres: (insp.genres ?? []).slice(0, 5),
    ...creator,
  };
  const ins = await rest("songs", { method: "POST", headers: { Prefer: "return=minimal" }, body: JSON.stringify(row) });
  if (!ins.ok) throw new Error(`Save ${ins.status}: ${(await ins.text()).slice(0, 200)}`);
  return { id };
}

// Voice off: the accompaniment alone, separated once and kept on the row.
async function separateVoice(id: string) {
  if (!/^[0-9a-f-]{36}$/.test(id)) throw new Error("Bad id");
  const rows = await (await rest(`songs?id=eq.${id}&select=audio_url,instrumental_url,voice`)).json();
  const row = rows?.[0];
  if (!row) throw new Error("Song not found");
  if (row.instrumental_url || !row.voice) return { instrumentalUrl: row.instrumental_url ?? row.audio_url };
  const audio = new Uint8Array(await (await fetch(row.audio_url)).arrayBuffer());
  const form = new FormData();
  form.append("file", new Blob([audio], { type: "audio/mpeg" }), "song.mp3");
  form.append("stem_variation_id", "two_stems_v1");
  const res = await fetch(`${ELEVEN}/music/stem-separation?output_format=mp3_44100_128`, {
    method: "POST",
    headers: { "xi-api-key": ELEVENLABS_MUSIC_API_KEY },
    body: form,
    signal: AbortSignal.timeout(140000),
  });
  if (!res.ok) throw new Error(`Stems ${res.status}: ${(await res.text()).slice(0, 200)}`);
  const files = unzipSync(new Uint8Array(await res.arrayBuffer()));
  const name = Object.keys(files).find((f) => /instrumental/i.test(f));
  if (!name) throw new Error("No instrumental stem");
  const url = await upload(`songs/${id}-instrumental.mp3`, files[name], "audio/mpeg");
  await rest(`songs?id=eq.${id}`, { method: "PATCH", body: JSON.stringify({ instrumental_url: url }) });
  return { instrumentalUrl: url };
}

// @ts-ignore: Deno.serve is the entry point for Supabase Edge Functions
Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
  try {
    const body = await req.json().catch(() => ({}));
    const action = body?.action;
    const language = typeof body?.language === "string" ? body.language.slice(0, 5) : "en";
    const insp = body?.inspiration as Inspiration | undefined;

    if (action === "status") return json({ music: Boolean(ELEVENLABS_MUSIC_API_KEY) });

    if (action === "stems") return json(await separateVoice(String(body?.id ?? "")));

    if (action === "generate") {
      if (!ELEVENLABS_MUSIC_API_KEY) return json({ error: "music_not_configured" }, 503);
      if (!insp?.artist || !body?.song?.parts?.length) return json({ error: "Missing song" }, 400);
      return json(await generate(req, body, insp, language));
    }

    if (action === "check") {
      const lines = strings(body?.lines, 12);
      const original = strings(body?.original, 12);
      const out = await luna(
        `You check song lyrics a user is editing (language "${language}"). First find the part's rhyme scheme from the ORIGINAL lines (which line endings rhyme with which). Then, for each EDITED line, say whether it still fits: its last word must rhyme (assonant or consonant) with its partner line, and its length must stay singable and close to the other lines. When a line breaks the rhyme, suggest 3 replacement words for its LAST word (synonyms or close meanings that restore the rhyme, same language). When it is too long, suggest a shorter version of the line. Reply with strict JSON {"lines":[{"ok":true}|{"ok":false,"issue":"rhyme"|"length","words":["..."],"shorter":"..."}]} with exactly one entry per line, in order.`,
        `Part: ${body?.part ?? "verse"}${original.length ? `\nOriginal lines:\n${original.map((l, i) => `${i + 1}. ${l}`).join("\n")}` : ""}\nEdited lines:\n${lines.map((l, i) => `${i + 1}. ${l}`).join("\n")}`,
        1500,
        "low",
      );
      const checks = (Array.isArray(out?.lines) ? out.lines : []).slice(0, lines.length).map((c: any) => ({
        ok: c?.ok !== false,
        issue: c?.issue === "length" ? "length" : c?.issue === "rhyme" ? "rhyme" : undefined,
        words: strings(c?.words, 3),
        shorter: typeof c?.shorter === "string" ? c.shorter.slice(0, 80) : undefined,
      }));
      return json({ lines: checks });
    }

    if (!insp?.artist) return json({ error: "Missing inspiration" }, 400);

    if (action === "ideas") {
      // Twists on what the song is ABOUT (its story, feeling or message), not random settings:
      // first name its intent, then bend it — so every idea is recognizably that song.
      const out = await luna(
        `The user wants to write an original song that creatively twists ${describe(insp)}.
First, from your knowledge and the description, state in one sentence the song's core intent: the story it tells, the feeling it carries or its message (for an artist or album: their signature themes).
Then suggest 5 creative twists ON THAT INTENT as punchy, playful pitches (max 7 words, no final period) in language "${language}", for example: the same story told by another character, the situation moved to another era or everyday place, the ending reversed, the feeling flipped (tragic → comic), the message answered or continued years later. Every idea must be clearly about this song's story or message — never a random setting or a plain genre swap. No quotes from the lyrics, no artist or song names.
Reply with strict JSON {"intent":"...","ideas":["..."]}.`,
        "Ideas",
        600,
        "low",
      );
      return json({ ideas: strings(out?.ideas, 5) });
    }

    if (action === "draft") {
      const idea = typeof body?.idea === "string" ? body.idea.trim().slice(0, 200) : "";
      const style = typeof body?.style === "string" ? body.style.slice(0, 60) : "";
      const out = await luna(
        `You write an original song inspired by ${describe(insp)}. ${inLanguage(language)} ${ORIGINAL_RULES}
${LINE_RULES}
Parts: verse 1 (4 lines), chorus (4 lines), verse 2 (4 lines), bridge (2–4 lines).${idea ? ` The user's idea for the song: "${idea}".` : ""}${style && style !== "original" ? ` It will be performed as ${style}.` : ""}
Also give:
- "title": a new title (not the inspiration's);
- "sound": the inspiration's musical style in ENGLISH, 8–15 words for a music generator (era, genre, instruments, vocals, tempo) with NO artist or song names;
- "instrumental": true only if the inspiration is an instrumental piece (no singing);
- "originalLanguage": the ISO 639-1 code of the language the inspiration is sung in (e.g. "en"; "" if instrumental);
- "moods": 3–5 one-to-three-word buttons (language "${language}") to rewrite a part with a different feeling, drawn from these lyrics and the inspiration (e.g. "Más alegre", "Más absurda", "Más bohemia").
Reply with strict JSON {"title":"","sound":"","instrumental":false,"originalLanguage":"","moods":[],"parts":[{"type":"verse","lines":[]},{"type":"chorus","lines":[]},{"type":"verse","lines":[]},{"type":"bridge","lines":[]}]}.`,
        `Inspiration: ${describe(insp)}`,
        1200,
      );
      const types = ["verse", "chorus", "verse", "bridge"] as const;
      const ids = ["verse1", "chorus", "verse2", "bridge"];
      const parts: Part[] = (Array.isArray(out?.parts) ? out.parts : []).slice(0, 4)
        .map((p: any, i: number) => ({ id: ids[i], type: types[i], lines: strings(p?.lines, 6) }))
        .filter((p: Part) => p.lines.length);
      if (parts.length < 2) throw new Error("Draft without lyrics");
      return json({
        song: {
          title: typeof out?.title === "string" ? out.title.slice(0, 80) : insp.title,
          sound: typeof out?.sound === "string" ? out.sound.slice(0, 200) : "",
          instrumental: out?.instrumental === true,
          originalLanguage: typeof out?.originalLanguage === "string" && /^[a-z]{2}$/.test(out.originalLanguage) ? out.originalLanguage : "",
          moods: strings(out?.moods, 5),
          parts,
        },
      });
    }

    if (action === "rewrite") {
      const song = body?.song as { title?: string; parts?: Part[] } | undefined;
      const part = (song?.parts ?? []).find((p) => p.id === body?.part);
      if (!part) return json({ error: "Unknown part" }, 400);
      const mood = typeof body?.mood === "string" ? body.mood.slice(0, 40) : "";
      const others = (song?.parts ?? []).filter((p) => p.id !== part.id).map((p) => `[${p.id}]\n${p.lines.join("\n")}`).join("\n\n");
      const out = await luna(
        `You rewrite ONE part of an original song inspired by ${describe(insp)}. ${inLanguage(language)} ${ORIGINAL_RULES}
${LINE_RULES}
${mood ? `Make this part ${mood}, keeping its place in the story.` : "Write a fresh alternative for this part, keeping its place in the story."} Same number of lines (${part.lines.length}). Keep it consistent with the rest of the song. Reply with strict JSON {"lines":[]}.`,
        `Song "${song?.title ?? ""}"\n\nOther parts:\n${others}\n\nPart to rewrite [${part.id}]:\n${part.lines.join("\n")}`,
        500,
      );
      const lines = strings(out?.lines, 6);
      if (!lines.length) throw new Error("Empty rewrite");
      return json({ lines });
    }

    return json({ error: "Unknown action" }, 400);
  } catch (err) {
    console.error("song-generate error", err);
    return json({ error: "Song service unavailable", detail: String(err).slice(0, 300) }, 500);
  }
});
